 where m.model_code in (select code from cfx_old);

update scm.product_models m
   set category = x.category::scm.mfg_product_category, allowed_options = coalesce(m.allowed_options, '{}'::jsonb) || x.allowed_options,
       updated_at = now()
  from cfx_models x
 where m.company_id = (select id from public.companies where code = 'HOUZS') and m.model_code = x.model_code and m.category::text = 'FURNITURE'
   and not exists (select 1 from scm.product_models m2 where m2.company_id = m.company_id and m2.model_code = x.model_code
                                                        and m2.category::text = x.category);

insert into scm.product_models (company_id, model_code, name, category, branding, allowed_options)
select (select id from public.companies where code = 'HOUZS'), x.model_code, o.name, x.category::scm.mfg_product_category, o.branding, x.allowed_options
  from cfx_models x join scm.mfg_products o on o.company_id = (select id from public.companies where code = 'HOUZS') and o.code = x.model_code
on conflict (company_id, model_code, category) do nothing;

insert into scm.mfg_products (id, company_id, code, name, category, uom, status, cost_price_sen, description, branding,
                              model_id, base_model, size_code, size_label)
select n.id, (select id from public.companies where code = 'HOUZS'), n.code, n.name, n.category::scm.mfg_product_category, o.uom, o.status::scm.mfg_product_status, 0,
       n.description, o.branding, m.id, n.base_model, n.size_code, n.size_label
  from cfx_new n
  join cfx_old o on o.code = n.old_code
  join scm.product_models m on m.company_id = (select id from public.companies where code = 'HOUZS') and m.model_code = n.base_model and m.category::text = n.category
on conflict (company_id, code) do nothing;

-- Linked to the same supplier as the SKU it replaces (HOOKKA), as main supplier; no cost (the catalogue has none).
insert into scm.supplier_material_bindings
    (company_id, supplier_id, material_kind, item_code, material_name, supplier_sku, unit_price_sen, price_valid_from, is_main_supplier, notes)
select (select id from public.companies where code = 'HOUZS'), b.supplier_id, 'mfg_product', n.code, n.name, n.supplier_sku, 0, null,
       not exists (select 1 from scm.supplier_material_bindings x where x.company_id = (select id from public.companies where code = 'HOUZS') and x.material_kind = 'mfg_product'
                                                                    and x.item_code = n.code and x.is_main_supplier),
       n.notes
  from cfx_new n
  join scm.supplier_material_bindings b on b.company_id = (select id from public.companies where code = 'HOUZS') and b.material_kind = 'mfg_product' and b.item_code = n.old_code
                                       and b.is_main_supplier
 where not exists (select 1 from scm.supplier_material_bindings x where x.company_id = (select id from public.companies where code = 'HOUZS') and x.material_kind = 'mfg_product'
                                                                   and x.item_code = n.code and x.supplier_id = b.supplier_id);

-- 1-3. What goes: the 13 "2990 list" sofas and the single SKUs replaced above (only those whose new SKUs now exist).
create temp table cfx_retire on commit drop as
select p.id, p.code, r.reason, 0::bigint as refs, ''::text as used_in
  from jsonb_to_recordset($cfx$[{"code": "SOF-HKA-5080", "reason": "2990"}, {"code": "SOF-HKA-5095", "reason": "2990"}, {"code": "SOF-HKA-5119", "reason": "2990"}, {"code": "SOF-HKA-8019", "reason": "2990"}, {"code": "SOF-HKA-8020", "reason": "2990"}, {"code": "SOF-HKA-8027", "reason": "2990"}, {"code": "SOF-HKA-9036", "reason": "2990"}, {"code": "SOF-HKA-9038", "reason": "2990"}, {"code": "SOF-HKA-9050", "reason": "2990"}, {"code": "SOF-HKA-9053", "reason": "2990"}, {"code": "SOF-HKA-9070", "reason": "2990"}, {"code": "SOF-HKA-9071", "reason": "2990"}, {"code": "SOF-HKA-AKEMI-UBORR", "reason": "2990"}, {"code": "BED-HKA-1003", "reason": "replaced"}, {"code": "BED-HKA-1005", "reason": "replaced"}, {"code": "BED-HKA-1007", "reason": "replaced"}, {"code": "BED-HKA-1008", "reason": "replaced"}, {"code": "BED-HKA-1009", "reason": "replaced"}, {"code": "BED-HKA-1013", "reason": "replaced"}, {"code": "BED-HKA-1019", "reason": "replaced"}, {"code": "BED-HKA-1023", "reason": "replaced"}, {"code": "BED-HKA-1030", "reason": "replaced"}, {"code": "BED-HKA-1041", "reason": "replaced"}, {"code": "BED-HKA-1051", "reason": "replaced"}, {"code": "BED-HKA-1052", "reason": "replaced"}, {"code": "BED-HKA-2003", "reason": "replaced"}, {"code": "BED-HKA-2006", "reason": "replaced"}, {"code": "BED-HKA-2008", "reason": "replaced"}, {"code": "BED-HKA-2009", "reason": "replaced"}, {"code": "BED-HKA-2010", "reason": "replaced"}, {"code": "BED-HKA-2011", "reason": "replaced"}, {"code": "BED-HKA-2023", "reason": "replaced"}, {"code": "BED-HKA-2027", "reason": "replaced"}, {"code": "BED-HKA-2033", "reason": "replaced"}, {"code": "BED-HKA-2038", "reason": "replaced"}, {"code": "BED-HKA-2041", "reason": "replaced"}, {"code": "BED-HKA-2049", "reason": "replaced"}, {"code": "BED-HKA-DIVAN", "reason": "replaced"}, {"code": "SOF-HKA-5530", "reason": "replaced"}, {"code": "SOF-HKA-5531", "reason": "replaced"}, {"code": "SOF-HKA-5535", "reason": "replaced"}, {"code": "SOF-HKA-5536", "reason": "replaced"}, {"code": "SOF-HKA-5537", "reason": "replaced"}, {"code": "SOF-HKA-5539", "reason": "replaced"}, {"code": "SOF-HKA-5540", "reason": "replaced"}, {"code": "SOF-HKA-5543", "reason": "replaced"}, {"code": "SOF-HKA-5545", "reason": "replaced"}, {"code": "SOF-HKA-5546", "reason": "replaced"}, {"code": "SOF-HKA-5547", "reason": "replaced"}, {"code": "SOF-HKA-5548", "reason": "replaced"}, {"code": "SOF-HKA-5549", "reason": "replaced"}, {"code": "SOF-HKA-6112", "reason": "replaced"}]$cfx$::jsonb) as r(code text, reason text)
  join scm.mfg_products p on p.company_id = (select id from public.companies where code = 'HOUZS') and p.code = r.code and p.category::text = 'FURNITURE'
 where (r.reason = '2990' or exists (select 1 from scm.mfg_products n where n.company_id = (select id from public.companies where code = 'HOUZS') and n.base_model = r.code))
   and not exists (select 1 from scm.entity_audit_log a where a.entity_type = 'mfg_product' and a.entity_id = p.code
                                                        and a.note like 'catalog-fix 2026-10%');

-- Anything that names the SKU besides its own supplier link and cost history: every item-code column of both engine
-- schemas (document lines, stock, price history, quotations, pwp, racks ...), and, for a replaced SKU, a photo.
do $$
declare t record; n bigint;
begin
  for t in
    select c.table_schema as s, c.table_name as tb, c.column_name as col
      from information_schema.columns c
      join information_schema.tables x on x.table_schema = c.table_schema and x.table_name = c.table_name and x.table_type = 'BASE TABLE'
     where c.table_schema in ('scm', 'public') and c.data_type = 'text'
       and c.column_name in ('item_code', 'product_code', 'new_item_code', 'trigger_item_code', 'redeemed_item_code', 'sku', 'ac_item_code')
       and not (c.table_schema = 'scm' and c.table_name in ('supplier_material_bindings', 'supplier_binding_price_history'))
  loop
    execute format('update pg_temp.cfx_retire r set refs = r.refs + q.n, used_in = r.used_in || %L || '' ''
                      from (select x.%I as code, count(*) as n from %I.%I x where x.%I in (select code from pg_temp.cfx_retire) group by 1) q
                     where q.code = r.code', t.s || '.' || t.tb, t.col, t.s, t.tb, t.col);
  end loop;
end $$;
update cfx_retire r set refs = r.refs + q.n, used_in = r.used_in || 'scm.mfg_product_photos '
  from (select product_id, count(*) as n from scm.mfg_product_photos group by 1) q
 where r.reason = 'replaced' and q.product_id = r.id;

insert into scm.entity_audit_log (company_id, entity_type, entity_id, action, actor_name_snapshot, field_changes, source, note)
select (select id from public.companies where code = 'HOUZS'), 'mfg_product', r.code, case when r.refs = 0 then 'delete' else 'deactivate' end, 'migration 0132', '[]'::jsonb, 'migration',
       'catalog-fix 2026-10: ' || case when r.reason = '2990' then 'owner 21 Oct 2026: the "2990 list" sofas must not be in the system'
                                  else 'owner 21 Oct 2026: replaced by one SKU per ' ||
                                       case when r.code like 'SOF-%' then 'compartment' else 'size' end || ' (base model ' || r.code || ')' end
       || case when r.refs = 0 then '; nothing named it, deleted with its supplier link and cost history'
               else '; still named in ' || trim(r.used_in) || ', so deactivated instead of deleted' end
  from cfx_retire r;

delete from scm.supplier_binding_price_history h using cfx_retire r
 where r.refs = 0 and h.company_id = (select id from public.companies where code = 'HOUZS') and h.material_kind = 'mfg_product' and h.item_code = r.code;
delete from scm.supplier_material_bindings b using cfx_retire r
 where r.refs = 0 and b.company_id = (select id from public.companies where code = 'HOUZS') and b.material_kind = 'mfg_product' and b.item_code = r.code;
delete from scm.mfg_products p using cfx_retire r where r.refs = 0 and p.id = r.id;
update scm.mfg_products p set status = 'INACTIVE', updated_at = now() from cfx_retire r where r.refs > 0 and p.id = r.id;
-- A model left with no SKU and still a plain Furniture model existed only for a deleted SKU.
delete from scm.product_models m using cfx_retire r
 where m.company_id = (select id from public.companies where code = 'HOUZS') and m.model_code = r.code and m.category::text = 'FURNITURE'
   and not exists (select 1 from scm.mfg_products p where p.model_id = m.id);

-- No supplier link may be left pointing at a SKU this file deleted.
do $$ begin
  if exists (select 1 from scm.supplier_material_bindings b join pg_temp.cfx_retire r on r.code = b.item_code
              where r.refs = 0 and b.company_id = (select id from public.companies where code = 'HOUZS')) then
    raise exception 'catalog fix: a supplier link still names a deleted SKU';
  end if;
end $$;

insert into scm.app_config (key, value, description, company_id)
select 'note:catalog-fix-2026-10',
       json_build_object('tag', 'catalog-fix 2026-10', 'at', now(), 'unit_changes', 99, 'units_added', array['NOS'],
                         'bedframe_skus', (select count(*) from cfx_new where category = 'BEDFRAME'),
                         'sofa_skus', (select count(*) from cfx_new where category = 'SOFA'),
                         'deleted', (select coalesce(array_agg(code order by code), '{}') from cfx_retire where refs = 0),
                         'deactivated', (select coalesce(array_agg(code order by code), '{}') from cfx_retire where refs > 0))::text,
       'Catalog fix note: catalog-fix 2026-10 (migration 0132)', (select id from public.companies where code = 'HOUZS')
 where exists (select 1 from cfx_old) or exists (select 1 from cfx_retire)
on conflict (key) do nothing;

notify pgrst, 'reload schema';
